231	/// Initiate the filesystem traversal tasks with the provided input paths and
232	/// run it to completion, returning the duration of the process
233	fn traverse_inputs(fs: &dyn FileSystem, inputs: Vec<OsString>, ctx: &TraversalOptions) -> Duration {
234	    let start = Instant::now();
235	    fs.traversal(Box::new(move |scope: &dyn TraversalScope| {
236	        for input in inputs {
237	            scope.spawn(ctx, PathBuf::from(input));
238	        }
239	    }));
240	
241	    start.elapsed()
242	}
